def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the digits
    digits = isbn.replace('-', '')

    # Check if the length is 10
    if len(digits) != 10:
        return isbn

    # Check if all characters are digits or the last one is 'X'
    for i, ch in enumerate(digits):
        if i < 9:
            if not ch.isdigit():
                return isbn
        else:
            if ch != 'X' and not ch.isdigit():
                return isbn

    # Calculate the checksum
    total = 0
    for i in range(9):
        total += int(digits[i]) * (10 - i)

    # The last digit (or X) should make the total divisible by 11
    last_char = digits[9]
    if last_char == 'X':
        last_value = 10
    else:
        last_value = int(last_char)

    total += last_value * 1

    if total % 11 == 0:
        return "Right"
    else:
        # Calculate the correct last digit
        # We need (sum of first 9 weighted + last_value) % 11 == 0
        # So last_value = (11 - (sum of first 9 weighted) % 11) % 11
        sum_first_9 = 0
        for i in range(9):
            sum_first_9 += int(digits[i]) * (10 - i)

        correct_last = (11 - (sum_first_9 % 11)) % 11
        if correct_last == 10:
            correct_last_char = 'X'
        else:
            correct_last_char = str(correct_last)

        # Reconstruct the ISBN with the correct last digit
        # The format is x-xxx-xxxxx-x
        # So we need to replace the last character
        corrected_digits = digits[:9] + correct_last_char
        # Reconstruct with hyphens in the same format
        corrected_isbn = f"{corrected_digits[0]}-{corrected_digits[1:4]}-{corrected_digits[4:9]}-{corrected_digits[9]}"
        return corrected_isbn
