def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Handle edge cases
    if m == 0 or n <= 0:
        return 0

    # Filter out items with price > n (they can't be bought)
    valid_items = [(price, value) for price, value in items if price <= n]

    if not valid_items:
        return 0

    # Use 1D DP for 0-1 knapsack
    dp = [0] * (n + 1)

    for price, value in valid_items:
        # Traverse from n down to price to avoid using the same item multiple times
        for j in range(n, price - 1, -1):
            if dp[j - price] + value > dp[j]:
                dp[j] = dp[j - price] + value

    return dp[n]
