def count_coprime_pairs(x0: int, y0: int) -> int:
    # Edge cases: if x0 or y0 is not positive, return 0
    if x0 <= 0 or y0 <= 0:
        return 0

    # If y0 is not divisible by x0, no valid pairs exist
    if y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0

    # Iterate through all possible factors 'a' of quotient
    for a in range(1, int(quotient ** 0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            # Check if a and b are co-prime
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a
